-- Generated by scripts/research/fetch-ookla-pilots.ts
-- Requires DuckDB with httpfs support.
install httpfs;
load httpfs;

create or replace temp view ookla_tiles as
select * from read_parquet('https://ookla-open-data.s3.amazonaws.com/parquet/performance/type=fixed/year=2026/quarter=1/2026-01-01_performance_fixed_tiles.parquet');

copy (
select
  'PHL' as iso3,
  'Philippines' as economy,
  'fixed' as network_type,
  count(*) as measured_tiles,
  sum(tests) as tests,
  sum(devices) as devices,
  round(avg(avg_d_kbps) / 1000, 2) as mean_download_mbps,
  round(avg(avg_u_kbps) / 1000, 2) as mean_upload_mbps,
  round(avg(avg_lat_ms), 2) as mean_latency_ms
from ookla_tiles
where tile_x between 116.9 and 127
  and tile_y between 4.5 and 21.3
union all
select
  'BGD' as iso3,
  'Bangladesh' as economy,
  'fixed' as network_type,
  count(*) as measured_tiles,
  sum(tests) as tests,
  sum(devices) as devices,
  round(avg(avg_d_kbps) / 1000, 2) as mean_download_mbps,
  round(avg(avg_u_kbps) / 1000, 2) as mean_upload_mbps,
  round(avg(avg_lat_ms), 2) as mean_latency_ms
from ookla_tiles
where tile_x between 88 and 92.8
  and tile_y between 20.5 and 26.7
) to 'research/digital-performance/generated/ookla-fixed-2026-q1-pilot-summary.csv' with (header, delimiter ',');
